export const WIDGET_CSS = "/* Spec: knowledge/components/adyen-agentic-commerce.md */\n/* The widget's own look, inlined into each UI resource: it loads no stylesheet or font. Every\n   control is at least 44 px tall, the touch target in knowledge/policies/ui-ux.md. */\n:root {\n  --bg: #ffffff;\n  --ink: #1d1d1f;\n  --muted: #6b6760;\n  --line: #e5e2dc;\n  --soft: #f5f3ef;\n  --accent: #004526;\n  --on-accent: #ffffff;\n  --ok: #1f6b3a;\n  --bad: #a33a2b;\n  --serif: \"Iowan Old Style\", \"Palatino Linotype\", Palatino, Georgia, serif;\n  --sans: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  color-scheme: light;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #161514;\n    --ink: #f2efe9;\n    --muted: #b4ada3;\n    --line: #3a3733;\n    --soft: #201f1d;\n    --accent: #7cc49a;\n    --on-accent: #0d1f15;\n    --ok: #7cc48b;\n    --bad: #f08a7a;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #161514;\n  --ink: #f2efe9;\n  --muted: #b4ada3;\n  --line: #3a3733;\n  --soft: #201f1d;\n  --accent: #7cc49a;\n  --on-accent: #0d1f15;\n  --ok: #7cc48b;\n  --bad: #f08a7a;\n  color-scheme: dark;\n}\n* {\n  box-sizing: border-box;\n}\nhtml,\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14px / 1.4 var(--sans);\n  -webkit-font-smoothing: antialiased;\n}\n#app {\n  padding: 10px;\n  max-width: 100%;\n  overflow-x: hidden;\n}\nh3 {\n  font: 600 14px / 1.3 var(--serif);\n  margin: 4px 0 0;\n}\np {\n  margin: 0;\n}\nbutton,\ninput {\n  font: inherit;\n  color: inherit;\n}\nbutton:focus-visible,\ninput:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n.top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n  margin-bottom: 8px;\n}\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-right: auto;\n}\n.mark {\n  display: grid;\n  place-items: center;\n  width: 28px;\n  height: 28px;\n  border-radius: 999px;\n  background: var(--accent);\n  color: var(--on-accent);\n  font: 600 12px / 1 var(--serif);\n}\n.name {\n  font: 600 16px / 1 var(--serif);\n}\n.badge {\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 1px 7px;\n  font-size: 11px;\n  color: var(--muted);\n}\n.tabs {\n  display: flex;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 2px;\n}\n.tab {\n  border: 0;\n  background: transparent;\n  border-radius: 999px;\n  min-height: 36px;\n  padding: 0 12px;\n  font-size: 13px;\n  cursor: pointer;\n}\n.tab[aria-current=\"page\"] {\n  background: var(--accent);\n  color: var(--on-accent);\n}\n.search {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n.search input {\n  flex: 1;\n  min-width: 0;\n  min-height: 44px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 0 12px;\n  background: var(--bg);\n}\n.btn {\n  min-height: 44px;\n  border: 1px solid var(--accent);\n  border-radius: 12px;\n  padding: 0 16px;\n  background: var(--accent);\n  color: var(--on-accent);\n  font-weight: 600;\n  cursor: pointer;\n  transition: opacity 150ms ease;\n}\n.btn.ghost {\n  background: transparent;\n  color: var(--accent);\n}\n.btn:disabled,\n.pill:disabled,\n.step:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n/* Each card is as tall as its own content: a short title never stretches to its neighbour's. */\n.rail {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  overflow-x: auto;\n  scroll-snap-type: x mandatory;\n  list-style: none;\n  margin: 0;\n  padding: 0 0 8px;\n}\n/* About two cards across a phone's panel: the conversation stays in view. */\n.card {\n  flex: 0 0 min(176px, 47%);\n  scroll-snap-align: start;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  border: 1px solid var(--line);\n  border-radius: 14px;\n  padding: 8px;\n}\n.card img,\n.noimg {\n  width: 100%;\n  height: auto;\n  aspect-ratio: 1;\n  border-radius: 10px;\n  background: var(--soft);\n  object-fit: cover;\n}\n.card .btn {\n  margin-top: 4px;\n}\n.price {\n  color: var(--muted);\n}\n.pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.pill {\n  position: relative;\n  min-height: 36px;\n  min-width: 36px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 0 10px;\n  background: transparent;\n  font-size: 13px;\n  cursor: pointer;\n}\n.pill[aria-pressed=\"true\"] {\n  border-color: var(--accent);\n  box-shadow: inset 0 0 0 1px var(--accent);\n}\n.empty,\n.count,\n.muted {\n  color: var(--muted);\n}\n.empty {\n  padding: 16px 0;\n}\n.count {\n  font-size: 12px;\n  margin: 6px 0;\n}\n.lines {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n.line {\n  display: grid;\n  grid-template-columns: 44px 1fr;\n  gap: 2px 10px;\n  align-items: center;\n  padding: 8px 0;\n  border-bottom: 1px solid var(--line);\n}\n.line img,\n.noimg.small {\n  width: 44px;\n  height: 44px;\n  border-radius: 10px;\n  background: var(--soft);\n}\n.line .qty,\n.line > .muted {\n  grid-column: 2;\n}\n.title {\n  font-weight: 600;\n}\n.qty {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.step {\n  position: relative;\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  background: transparent;\n  cursor: pointer;\n}\n.link {\n  min-height: 44px;\n  border: 0;\n  background: transparent;\n  color: var(--accent);\n  text-decoration: underline;\n  text-underline-offset: 3px;\n  cursor: pointer;\n}\n.totals {\n  margin: 12px 0;\n}\n.row {\n  display: flex;\n  justify-content: space-between;\n  padding: 2px 0;\n}\n.row dt,\n.row dd {\n  margin: 0;\n}\n.row.strong {\n  font-weight: 700;\n}\n.row.ok,\n.muted.ok {\n  color: var(--ok);\n}\n.problems {\n  color: var(--bad);\n  padding-left: 18px;\n}\n.actions {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.cards {\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 8px 12px;\n  margin: 0;\n}\n.cards legend {\n  font-size: 13px;\n  color: var(--muted);\n}\n.radio {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 44px;\n}\n.radio input {\n  accent-color: var(--accent);\n}\n.note {\n  min-height: 1.4em;\n  margin-top: 10px;\n  font-size: 13px;\n}\n.note.ok {\n  color: var(--ok);\n}\n.note.bad {\n  color: var(--bad);\n}\n.note.info {\n  color: var(--muted);\n}\n@media (prefers-reduced-motion: reduce) {\n  * {\n    transition: none !important;\n    scroll-behavior: auto !important;\n  }\n}\n\n/* Drawn small, touched at 44 px: the hit area reaches 4 px past the edge, and an 8 px gap keeps\n   neighbouring areas apart (UI policy). */\n.pill::after,\n.step::after,\n.tab::after,\n.details::after {\n  content: \"\";\n  position: absolute;\n  inset: -4px;\n}\n.tab,\n.details {\n  position: relative;\n}\n.card .details {\n  margin-top: 0;\n  font-size: 13px;\n}\n/* Safari on a phone zooms into a field under 16 px; the frame's search must not. */\n@media (pointer: coarse) {\n  .search input {\n    font-size: 16px;\n  }\n}\n";
export const PLUGIN_FILES: Record<string, string> = {
  "assets/icon.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 48 48\" role=\"img\" aria-label=\"Atelier Velune\"><rect width=\"48\" height=\"48\" rx=\"12\" fill=\"#004526\"/><text x=\"24\" y=\"31\" text-anchor=\"middle\" font-family=\"Georgia, serif\" font-size=\"18\" font-weight=\"600\" fill=\"#ffffff\">AV</text></svg>\n",
  "assets/logo.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 96 96\" role=\"img\" aria-label=\"Atelier Velune\"><circle cx=\"48\" cy=\"48\" r=\"48\" fill=\"#004526\"/><text x=\"48\" y=\"58\" text-anchor=\"middle\" font-family=\"Georgia, serif\" font-size=\"34\" font-weight=\"600\" fill=\"#ffffff\">AV</text></svg>\n",
  "mcp.json": "{\n  \"$schema\": \"https://agent-plugins.org/schemas/1.0.0/mcp.schema.json\",\n  \"mcpServers\": {\n    \"atelier-velune\": {\n      \"type\": \"streamable-http\",\n      \"url\": \"https://agentic.payments-playground.com/mcp\",\n      \"extensions\": {\n        \"com.openai\": {\n          \"auth\": {\n            \"type\": \"oauth\",\n            \"client\": {\n              \"mode\": \"cimd\"\n            }\n          }\n        }\n      }\n    }\n  }\n}\n",
  "plugin.json": "{\n  \"$schema\": \"https://agent-plugins.org/schemas/1.0.0/plugin.schema.json\",\n  \"name\": \"atelier-velune\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Shop Atelier Velune, a demo fashion store on Adyen TEST: browse the collection by hand or let your assistant shop, then pay with a card saved in your store account.\",\n  \"author\": {\n    \"name\": \"Payments Playground\",\n    \"url\": \"https://agentic.payments-playground.com\"\n  },\n  \"homepage\": \"https://agentic.payments-playground.com/docs/chatgpt\",\n  \"keywords\": [\"shopping\", \"fashion\", \"ucp\", \"pap\", \"adyen\", \"test\"],\n  \"extensions\": {\n    \"com.openai\": {\n      \"interface\": {\n        \"displayName\": \"Atelier Velune\",\n        \"shortDescription\": \"Adyen TEST demo fashion store\",\n        \"longDescription\": \"Browse the Atelier Velune collection in a carousel, choose colour and size, fill your bag and pay with a card saved in your store account, within the budget you set when you connect. Payments run on Adyen TEST: no real money moves.\",\n        \"developerName\": \"Payments Playground\",\n        \"category\": \"Other\",\n        \"capabilities\": [\"Browse catalogue\", \"Manage bag\", \"Pay with saved card (TEST)\"],\n        \"websiteURL\": \"https://agentic.payments-playground.com\",\n        \"supportURL\": \"https://agentic.payments-playground.com/docs/chatgpt\",\n        \"privacyPolicyURL\": \"https://agentic.payments-playground.com/legal#privacy\",\n        \"termsOfServiceURL\": \"https://agentic.payments-playground.com/legal#terms\",\n        \"defaultPrompt\": [\n          \"Find me a trench coat from Atelier Velune.\",\n          \"Show me bags under 150 EUR.\",\n          \"Show my Atelier Velune bag.\"\n        ],\n        \"brandColor\": \"#004526\",\n        \"logo\": \"./assets/logo.svg\",\n        \"composerIcon\": \"./assets/icon.svg\"\n      }\n    }\n  }\n}\n",
  "skills/personal-stylist/SKILL.md": "---\nname: personal-stylist\ndescription: Shop Atelier Velune with the shopper like a boutique adviser. Use when the shopper wants clothes, bags or accessories from Atelier Velune, or asks to see, add to or pay for their Atelier Velune bag.\n---\n\n# Personal stylist for Atelier Velune\n\nAtelier Velune is a demo fashion store on Adyen TEST: its products are fictional and no real\nmoney moves. Its tools follow UCP: `search_catalog`, `get_product`, the cart tools, the checkout\ntools and `get_order`.\n\n## How to help\n\n1. Before showing products, ask two short questions: the occasion, and the colours the shopper\n   likes. Skip them when the shopper already said, or asks to see everything.\n2. Show products with `search_catalog`; the store's carousel shows them with colour and size.\n3. The shopper may shop by hand in the carousel or the bag, or ask you. When they change their\n   bag by hand, the widget tells you the cart or checkout id: keep using that one.\n4. Add only what the shopper chose, in the colour and size they chose. Variant ids come from the\n   catalogue; never invent one, and never send a price.\n5. Pay only when the shopper asks you to, with `complete_checkout` and a card the checkout lists\n   in `payment.instruments`. Say the total and the card (brand and last digits) first.\n6. If the answer is `requires_escalation`, give the shopper `continue_url`; over the budget, they\n   may raise it at `agent_budget.manage_url`, then you complete again.\n\n## Never\n\n- Ask the shopper for a card number, a CVC or a password: the store keeps the card, and the\n  shopper confirms on the store's own pages.\n- Pay more than once for one checkout, or retry a refused payment without the shopper's word.\n"
};
